delete from public.self_host_app_category_links where app_id in (select id from public.self_host_apps where slug in ('addarr', 'adguard-exporter', 'adguard-home', 'adguard-home-11notes', 'adguardbuddy', 'adguardhome-sync', 'adguardhome-unbound-redis', 'admidio', 'adsb-radarbox', 'advanced-automations', 'advanced-listdiff', 'adventurelog', 'ae-netscope', 'aegis-mfa', 'affine-community-edition', 'affine-self-hosted'));

insert into public.self_host_app_category_links(app_id,category_id)
select a.id,c.id from (values
 ('addarr','automation'),
 ('addarr','communication'),
 ('adguard-exporter','monitoring-status'),
 ('adguard-exporter','networking-dns'),
 ('adguard-home','networking-dns'),
 ('adguardbuddy','dashboards'),
 ('adguardbuddy','monitoring-status'),
 ('adguardbuddy','networking-dns'),
 ('adguardhome-sync','networking-dns'),
 ('adguardhome-unbound-redis','networking-dns'),
 ('admidio','communities-social'),
 ('admidio','forms-polls-events'),
 ('adsb-radarbox','maps-travel'),
 ('advanced-automations','automation'),
 ('advanced-automations','home-automation-iot'),
 ('adventurelog','maps-travel'),
 ('ae-netscope','networking-dns'),
 ('ae-netscope','system-admin-hosting'),
 ('aegis-mfa','identity-access'),
 ('aegis-mfa','security-privacy'),
 ('affine-community-edition','knowledge-notes'),
 ('affine-community-edition','project-task-management')
) v(slug,category_slug)
join public.self_host_apps a on a.slug=v.slug join public.self_host_app_categories c on c.slug=v.category_slug on conflict(app_id,category_id) do nothing;

