 options='[{"label":"Docker image","method":"docker","support_level":"official","image":"ghcr.io/toeverything/affine:stable","url":"https://github.com/toeverything/affine/pkgs/container/affine","source_url":"https://github.com/toeverything/affine/pkgs/container/affine","note":"Official image; the Compose deployment is the recommended complete server stack.","sort_order":10},{"label":"Docker Compose","method":"compose","support_level":"official","image":"ghcr.io/toeverything/affine:stable","url":"https://github.com/toeverything/AFFiNE/blob/canary/.docker/selfhost/compose.yml","source_url":"https://github.com/toeverything/AFFiNE/blob/canary/.docker/selfhost/compose.yml","note":"Official self-host stack includes PostgreSQL and Redis-compatible cache plus persistent workspace storage.","sort_order":20},{"label":"TrueNAS catalog","method":"truenas_scale","support_level":"community","image":null,"url":"https://apps.truenas.com/catalog/affine_community/","source_url":"https://apps.truenas.com/catalog/affine_community/","note":"Community-maintained TrueNAS package.","sort_order":30},{"label":"Umbrel community Compose","method":"compose","support_level":"community","image":"ghcr.io/toeverything/affine:0.27.4@sha256:b649f5ce2384ffdf13c23bccf81d759e15973d59d0b0058af65d895a84373099","url":"https://raw.githubusercontent.com/getumbrel/umbrel-apps/master/affine/docker-compose.yml","source_url":"https://raw.githubusercontent.com/getumbrel/umbrel-apps/master/affine/docker-compose.yml","note":"Community-maintained Umbrel Compose package.","sort_order":40},{"label":"Umbrel catalog","method":"umbrel","support_level":"community","image":null,"url":"https://github.com/getumbrel/umbrel-apps/tree/master/affine","source_url":"https://github.com/getumbrel/umbrel-apps/tree/master/affine","note":"Community-maintained Umbrel package.","sort_order":50}]'::jsonb,
 checked_at=now(),
 updated_at=now()
where app_id=(select id from public.self_host_apps where slug='affine-community-edition');

do $post_update_guard$
begin
 if (select count(*) from public.self_host_apps where slug in ('addarr', 'adguard-exporter', 'adguard-home', 'adguardbuddy', 'adguardhome-sync', 'adguardhome-unbound-redis', 'admidio', 'adsb-radarbox', 'advanced-automations', 'adventurelog', 'ae-netscope', 'aegis-mfa', 'affine-community-edition') and published=true and self_hosting_status='self_hostable') <> 13 then raise exception 'Batch 21 app corrections failed'; end if;
 if (select count(*) from public.self_host_app_resource_estimates e join public.self_host_apps a on a.id=e.app_id where a.slug in ('addarr', 'adguard-exporter', 'adguard-home', 'adguardbuddy', 'adguardhome-sync', 'adguardhome-unbound-redis', 'admidio', 'adsb-radarbox', 'advanced-automations', 'adventurelog', 'ae-netscope', 'aegis-mfa', 'affine-community-edition') and e.ram_estimate_kind='estimated' and e.storage_estimate_kind='estimated' and e.ram_estimate_basis is not null and e.storage_estimate_basis is not null) <> 13 then raise exception 'Batch 21 estimate update check failed'; end if;
 if not exists(select 1 from public.self_host_apps where slug='adguard-home-11notes' and published=false) then raise exception 'adguard-home-11notes publication cleanup failed'; end if;
 if not exists(select 1 from public.self_host_apps where slug='advanced-listdiff' and published=false) then raise exception 'advanced-listdiff publication cleanup failed'; end if;
 if not exists(select 1 from public.self_host_apps where slug='affine-self-hosted' and published=false) then raise exception 'affine-self-hosted publication cleanup failed'; end if;
end;
$post_update_guard$;
commit;
